content:
900          mem[len - 1] = 0;
   901        }
   902        else if(c == '\n') {
   903          parser->offsets.filename = parser->item_offset;
   904          mem[len - 1] = 0;
   905          result = ftp_pl_insert_finfo(data, infop);
   906          if(result)
   907            return result;
   908
   909          parser->state.NT.main = PL_WINNT_DATE;
   910          parser->state.NT.sub.filename = PL_WINNT_FILENAME_PRESPACE;
   911        }
   912        break;
   913      case PL_WINNT_FILENAME_WINEOL:
   914        if(c == '\n') {
   915          parser->offsets.filename = parser->item_offset;
   916          result = ftp_pl_insert_finfo(data, infop);
   917          if(result)
   918            return result;
   919
   920          parser->state.NT.main = PL_WINNT_DATE;
   921          parser->state.NT.sub.filename = PL_WINNT_FILENAME_PRESPACE;
   922        }
   923        else
   924          return CURLE_FTP_BAD_FILE_LIST;
   925
   926        break;
   927      }
   928      break;
   929    }
   930
   931    return CURLE_OK;
   932  }
